import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect{public static void main(String[]a)throws Exception{int count=0;try(var z=new ZipFile(a[0])){for(var e:Collections.list(z.entries()))if((e.getName().startsWith("net/flashlight/battery/")||e.getName().equals("net/flashlight/mixin/CaptureStage9.class"))&&e.getName().endsWith(".class")){var c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);for(var m:c.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);if(c.name.endsWith("/Engine6"))for(var m:c.methods)if(m.name.equals("albedo"))for(var i:m.instructions)if(i instanceof LdcInsnNode l&&Set.of("getEntityRenderDispatcher","getBlockEntityRenderDispatcher","entitiesForRendering").contains(l.cst))throw new AssertionError("capture must not render entities or furniture again");count++;}}System.out.println("BATTERY_CLASSES_BYTECODE_AND_NO_SECOND_ENTITY_DRAW_CHECKS="+count);}}
